Here is a C++ function that converts markdown formatted text to HTML formatted text:

```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex(R"(#\s*([a-zA-Z\s]+))");
    std::smatch match;
    if (std::regex_search(html, match, regex)) {
        html = "<h1>" + match[1] + "</h1>";
    }
    return html;
}

int main() {
    std::string markdown = "# My Title\nThis is my text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to match the title of the markdown text and replaces it with an HTML `<h1>` tag. The regular expression `#\s*([a-zA-Z\s]+)` matches the `#` character followed by zero or more whitespace characters and one or more alphabetical or whitespace characters, capturing the title of the markdown text. The `std::regex_search` function is used to find the first match in the markdown text, and the captured title is replaced with an HTML `<h1>` tag.

